// One enchanted item for sale in Reznar's catalog.
type Item struct {
	ID        pgtype.UUID
	CreatedAt pgtype.Timestamptz
	UpdatedAt pgtype.Timestamptz
	// Item title as printed (e.g. 'Amulet of Amplified Emotion').
	Name interface{}
	// Canonical top-level kind, normalized from the type line ('Wonderous' typo folded).
	Category ItemCategory
	// Canonical rarity grade. NULL when the source says 'varies' — the per-variant grades then live in item_variant — or when genuinely unstated.
	Rarity *Rarity
	// True for single-use items (potions). Kept as data, not derived from category, so a future consumable wondrous item needs no schema change.
	IsConsumable bool
	// Whether the item consumes one of its user's attunement slots.
	RequiresAttunement bool
	// Canonical body/hand slot; the one-object-per-slot rule keys on this.
	WornSlot *WornSlot
	// stated = the source names where it is worn; inferred = derived from category.
	WornSlotProvenance *SlotProvenance
	// For wielded items, how many hands it occupies (a greatsword needs 2).
	HandsRequired *int16
	// Shape of the base-item constraint from the type-line parenthetical; NULL when the type line has none.
	Applicability *ApplicabilityKind
	// The single base item this enchantment applies to, when applicability = specific.
	BaseItemID pgtype.UUID
	// Family quantifier for 'any sword'-style constraints.
	AppliesWeaponFamily *WeaponFamily
	// Minimum armor weight for 'any medium or heavy armor'-style constraints (enum order is light < medium < heavy).
	AppliesMinArmorWeight *ArmorWeight
	// True only when the source explicitly marks the item cursed.
	IsCursed bool
	// Verbatim curse or detrimental-property wording (artifact vulnerabilities, costs of use).
	CurseOrDrawbackText *string
	// The italic type line verbatim, misspellings included — provenance for every normalized facet.
	TypeLine interface{}
	// The source's own wear/wield phrase, when it states one — provenance for worn_slot.
	WornPhraseRaw *string
	// Complete body prose, verbatim, stitched across page breaks.
	Description string
	// First PDF page (1-based) the item appears on in data/items_combined.pdf.
	PdfPageStart int16
	// Last PDF page the item's prose runs onto.
	PdfPageEnd int16
}

